mapper.select:
select

from survey_channel_model_info m
where m.model_id = #{modelId,jdbcType=BIGINT} and m.task_id = #{taskId,jdbcType=BIGINT} and m.task_content_id = #{taskContentId,jdbcType=BIGINT} and m.task_content_result_id = #{taskContentResutlId,jdbcType=BIGINT}
and m.area_categories_id = (
    select c.area_categories_id from survey_channel_model_area_city c where c.area_id = #{areaId,jdbcType=BIGINT} and c.model_id = #{modelId,jdbcType=BIGINT} limit 1
)
